export function makeQuestions(subject,count,seed,settings={}){
 const r=rng(seed),int=(a,b)=>a+Math.floor(r()*(b-a+1));
 if(subject==='lang'){const categories=['ひらがな','カタカナ','かんじ','ことば','ぶんを よもう'];const pools=Object.fromEntries(categories.map(c=>[c,shuffle(langBank.filter(q=>q[0]===c),r)]));return Array.from({length:count},(_,i)=>{const c=categories[i%5],q=pools[c][Math.floor(i/5)%pools[c].length];return{kind:'lang',tag:q[0],text:q[1],answer:q[2],options:shuffle(q[3],r),hint:q[4],explain:`こたえは「${q[2]}」だね。`};});}
 const kinds=subject==='math'?(settings.multiply===false?['calc','word','clock']:['calc','multiply','word','clock']):[subject];
 return Array.from({length:count},(_,i)=>{const kind=kinds[i%kinds.length];if(kind==='clock'){
  const h=int(1,12),m=(settings.clock==='five'?[0,5,10,15,20,25,30,35,40,45,50,55]:[0,30])[int(0,settings.clock==='five'?11:1)];const answer=`${h}じ${m?` ${m}ふん`:''}`;
  const options=shuffle([answer,`${h===12?1:h+1}じ${m?` ${m}ふん`:''}`,`${h}じ${m===0?' 30ふん':''}`,`${h===1?12:h-1}じ${m?` ${m}ふん`:''}`],r);
  return{kind,tag:'とけい',text:'いま、なんじ なんぷん？',h,m,answer,options,hint:'みじかい はりが「じ」。ながい はりが「ふん」だよ。\nながい はりは、12が 0ふん、6が 30ふん。1めもりは 1ぷんだよ。',explain:`みじかい はりは ${h}じ${m?'を すぎた ところ':''}。ながい はりは ${m}ふん。${answer}だね。`};
 }if(kind==='multiply'){
  const a=int(1,3),b=int(1,9),answer=String(a*b);return{kind,tag:`かけざん・${a}の だん`,text:`${a} × ${b} ＝ ？`,a,b,answer,options:numberOptions(a*b,r),hint:`${a}こずつが ${b}くみだよ。\n${Array.from({length:b},()=>a).join(' ＋ ')} を たしてみよう。`,explain:`${a}こずつ ${b}くみで ${a*b}こ。${a} × ${b} ＝ ${a*b} だね。`};
 }if(kind==='word'){
  const a=int(2,8),b=int(1,settings.range===20?Math.min(8,20-a):10-a),minus=r()>.5,n=minus?a-b:a+b;
  if(minus){const total=a+b;return{kind,tag:'ぶんしょうだい',text:`きのみが ${total}こ あります。\nピカチュウが ${b}こ たべました。\nのこりは なんこ？`,answer:`${a}こ`,options:numberOptions(a,r,v=>`${v}こ`),hint:`${total}こから、たべた ${b}こを ひくよ。\n${total} − ${b} ＝ ？`,explain:`${total} − ${b} ＝ ${a}。のこりは ${a}こだね。`};}
  return{kind,tag:'ぶんしょうだい',text:`イーブイが ${animal(a)} います。\nあとから ${animal(b)} きました。\nあわせて なんびき？`,answer:animal(n),options:numberOptions(n,r,animal),hint:`さいしょの ${animal(a)}と、あとから きた ${animal(b)}を たすよ。\n${a} ＋ ${b} ＝ ？`,explain:`${a} ＋ ${b} ＝ ${n}。あわせて ${animal(n)}だね。`};
 }const limit=settings.range===20?20:10,a=int(1,limit-1),b=int(1,limit-a),minus=r()>.5,total=a+b,answer=minus?a:total;
 return{kind:'calc',tag:minus?'ひきざん':'たしざん',text:minus?`${total} − ${b} ＝ ？`:`${a} ＋ ${b} ＝ ？`,answer:String(answer),options:numberOptions(answer,r),dots:minus?total:null,hint:minus?`${total}こから ${b}こを とってみよう。`:`${a}こに ${b}こを たしてみよう。`,explain:minus?`${total} − ${b} ＝ ${a} だね。`:`${a} ＋ ${b} ＝ ${total} だね。`};});
}
export function clockSvg(h,m){const minute=m*6,hour=(h%12)*30+m*.5;return`<svg class="clock" viewBox="0 0 240 240" role="img" aria-label="もんだいの とけい"><circle cx="120" cy="120" r="114" fill="#fff" stroke="#d7d9c8" stroke-width="5"/>${Array.from({length:60},(_,i)=>`<line x1="120" y1="${i%5===0?14:12}" x2="120" y2="${i%5===0?24:17}" transform="rotate(${i*6} 120 120)" stroke="${i%5===0?'#687665':'#c9cdbe'}" stroke-width="${i%5===0?3:1}"/>`).join('')}${Array.from({length:12},(_,i)=>{const n=i+1,a=n*Math.PI/6;return`<text x="${120+82*Math.sin(a)}" y="${127-82*Math.cos(a)}" text-anchor="middle" font-size="19" fill="#354337" font-weight="700">${n}</text>`;}).join('')}<line x1="120" y1="120" x2="120" y2="62" transform="rotate(${hour} 120 120)" stroke="#d78350" stroke-width="9" stroke-linecap="round"/><line x1="120" y1="120" x2="120" y2="38" transform="rotate(${minute} 120 120)" stroke="#4e8064" stroke-width="5" stroke-linecap="round"/><circle cx="120" cy="120" r="7" fill="#354337"/></svg>`;}
